raw_response:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 10^6",
      "description": "The number of glades in the park is between 1 and 10^6, inclusive."
    },
    {
      "id": "P2",
      "expression": "0 <= m <= 10^6",
      "description": "The number of trails in the park is between 0 and 10^6, inclusive."
    },
    {
      "id": "P3",
      "expression": "1 <= xi, yi <= n",
      "description": "Each trail connects two glades within the range of 1 to n."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output == 0 or output >= 1",
      "description": "The output is either 0 if Vasya's walk is possible, or the minimum number of trails to be added to make the walk possible."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "expression": "all(1 <= xi <= n and 1 <= yi <= n for xi, yi in trails)",
      "description": "Each trail connects two existing glades within the park."
    },
    {
      "id": "I2",
      "expression": "all(xi != yi for xi, yi in trails)",
      "description": "No trail connects a glade to itself."
    },
    {
      "id": "I3",
      "expression": "all(xi != xj or yi != yj for i < j for xi, yi, xj, yj in trails)",
      "description": "No two trails connect the same pair of glades."
    },
    {
      "id": "I4",
      "expression": "all(all(xi != xj and yi != yj for xj, yj in trails if (xi, yi) != (xj, yj)) for xi, yi in trails)",
      "description": "No trail connects the same pair of glades as any other trail."
    }
  ]
}
